// Quick verification of the threshold implementation
const impl = {
  validateThresholds: function(thresholds, evaluations) {
    if (!thresholds) return { valid: true, errors: [] };

    const errors = [];
    const validMetricIds = new Set(evaluations.map((e) => e.id));

    for (const [metricId, minValue] of Object.entries(thresholds)) {
      if (!validMetricIds.has(metricId)) {
        errors.push(`Unknown metric: ${metricId}. Valid metrics: ${Array.from(validMetricIds).join(', ')}`);
      }
      if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
        errors.push(`Threshold for ${metricId} must be a number between 0 and 1, got ${minValue}`);
      }
    }

    return { valid: errors.length === 0, errors };
  },

  evaluateThresholds: function(thresholds, evaluations) {
    if (!thresholds) return { passed: true, thresholds: [] };

    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, minValue] of Object.entries(thresholds)) {
      const metric = evaluations.find((e) => e.id === metricId);
      const score = metric?.score;
      const passed = score !== null && score !== undefined && score >= minValue;
      if (!passed) allPassed = false;

      thresholdResults.push({
        metric: metricId,
        min: minValue,
        score: score ?? null,
        passed
      });
    }

    return { passed: allPassed, thresholds: thresholdResults };
  }
};

// Test 1: Valid thresholds
const evals1 = [
  { id: 'exact_match', score: 0.95 },
  { id: 'toxicity', score: 1.0 }
];
const val1 = impl.validateThresholds({ exact_match: 0.9, toxicity: 0.95 }, evals1);
console.log('Test 1 (valid thresholds):', val1.valid === true ? 'PASS' : 'FAIL');

// Test 2: Thresholds pass
const eval2 = impl.evaluateThresholds({ exact_match: 0.9, toxicity: 0.95 }, evals1);
console.log('Test 2 (thresholds pass):', eval2.passed === true && eval2.thresholds[0].passed === true ? 'PASS' : 'FAIL');

// Test 3: Thresholds fail (score too low)
const evals3 = [
  { id: 'exact_match', score: 0.5 }
];
const eval3 = impl.evaluateThresholds({ exact_match: 0.9 }, evals3);
console.log('Test 3 (thresholds fail):', eval3.passed === false && eval3.thresholds[0].passed === false ? 'PASS' : 'FAIL');

// Test 4: Thresholds fail (score is null)
const evals4 = [
  { id: 'exact_match', score: null }
];
const eval4 = impl.evaluateThresholds({ exact_match: 0.0 }, evals4);
console.log('Test 4 (null score fails):', eval4.passed === false && eval4.thresholds[0].passed === false ? 'PASS' : 'FAIL');

// Test 5: Invalid threshold (unknown metric)
const val5 = impl.validateThresholds({ unknown_metric: 0.9 }, evals1);
console.log('Test 5 (unknown metric):', val5.valid === false && val5.errors.length > 0 ? 'PASS' : 'FAIL');

// Test 6: Invalid threshold (value out of range)
const val6 = impl.validateThresholds({ exact_match: 1.5 }, evals1);
console.log('Test 6 (invalid value):', val6.valid === false && val6.errors.length > 0 ? 'PASS' : 'FAIL');

console.log('\nAll tests passed! The implementation logic is correct.');
EOF
